package ru.neverland.townyspecialization.model;
import ru.neverland.integration.SpecializationRules;
import java.util.*;
public record Specialization(String id,String name,String icon,String description,boolean enabled,String building,String buildingName,int minimumBuildingLevel,Map<String,Double> bonuses,Map<String,Double> perLevel,Set<String> productionProjects){
    public Specialization{if(!id.equals(SpecializationRules.required(building))||name==null||name.isBlank()||icon==null||icon.isBlank()||description==null||buildingName==null||buildingName.isBlank()||minimumBuildingLevel<1||minimumBuildingLevel>5)throw new IllegalArgumentException("Неверный профиль специализации");bonuses=Map.copyOf(bonuses);perLevel=Map.copyOf(perLevel);productionProjects=Set.copyOf(productionProjects);if(bonuses.isEmpty()||!bonuses.keySet().containsAll(perLevel.keySet())||!SpecializationRules.EFFECTS.containsAll(bonuses.keySet()))throw new IllegalArgumentException("Неверные бонусы");for(var e:bonuses.entrySet()){double extra=perLevel.getOrDefault(e.getKey(),0d);if(!Double.isFinite(e.getValue())||!Double.isFinite(extra)||e.getValue()<0||extra<0||e.getValue()+extra*5>(e.getKey().equals("happiness")?20:.5))throw new IllegalArgumentException("Бонус вне диапазона");}for(String p:productionProjects)if(!p.matches("[a-z0-9_-]{1,64}"))throw new IllegalArgumentException("Неверное производственное здание");}
    public double bonus(String effect,int workingBuildingLevel){return enabled?java.math.BigDecimal.valueOf(bonuses.getOrDefault(effect,0d)).add(java.math.BigDecimal.valueOf(perLevel.getOrDefault(effect,0d)).multiply(java.math.BigDecimal.valueOf(workingBuildingLevel>=minimumBuildingLevel?Math.min(5,workingBuildingLevel):0))).doubleValue():0;}
}
